#pragma once
#include "Arduino.h"
class Preferences{std::string ns;bool ro=false;public:inline static std::map<std::string,std::string> values;inline static std::string file;
static void load(){std::ifstream f(file);std::string k,v;while(f>>std::quoted(k)>>std::quoted(v))values[k]=v;}static void flush(){if(file.empty())return;std::ofstream f(file+".tmp");for(auto&[k,v]:values)f<<std::quoted(k)<<' '<<std::quoted(v)<<'\n';f.close();std::rename((file+".tmp").c_str(),file.c_str());}
void begin(const char*n,bool read=false){ns=std::string(n)+"/";ro=read;}void end(){if(!ro)flush();}bool isKey(const char*k){return values.count(ns+k);}int getInt(const char*k,int d=0){return isKey(k)?std::atoi(values[ns+k].c_str()):d;}unsigned long getULong(const char*k,unsigned long d=0){return isKey(k)?std::strtoul(values[ns+k].c_str(),nullptr,10):d;}bool getBool(const char*k,bool d=false){return getInt(k,d)!=0;}String getString(const char*k,const char*d=""){return isKey(k)?values[ns+k]:String(d);}void putInt(const char*k,int v){if(!ro)values[ns+k]=std::to_string(v);}void putULong(const char*k,unsigned long v){if(!ro)values[ns+k]=std::to_string(v);}void putBool(const char*k,bool v){putInt(k,v);}void putString(const char*k,String v){if(!ro)values[ns+k]=v;}void putBytes(const char*k,const void*p,size_t n){const char*hex="0123456789abcdef";std::string s;for(size_t i=0;i<n;i++){unsigned c=((const unsigned char*)p)[i];s+=hex[c>>4];s+=hex[c&15];}if(!ro)values[ns+k]=s;}void getBytes(const char*k,void*p,size_t n){auto s=values[ns+k];for(size_t i=0;i<n&&i*2+1<s.size();i++)((unsigned char*)p)[i]=std::stoi(s.substr(i*2,2),nullptr,16);}void clear(){for(auto it=values.begin();it!=values.end();){if(it->first.rfind(ns,0)==0)it=values.erase(it);else ++it;}}};
